import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.min
import kotlin.math.max

val reader = BufferedReader(InputStreamReader(System.`in`))
var st: StringTokenizer? = null

fun readstring(): String {
    return reader.readLine().trimEnd()
}

fun readint(): Int {
    return readstring().toInt()
}

fun read_line_of_integers(): List<Int> {
    st = StringTokenizer(readstring())
    val list = mutableListOf<Int>()
    while (st!!.hasMoreTokens()) {
        list.add(st!!.nextToken().toInt())
    }
    return list
}

fun read_line_of_longs(): List<Long> {
    st = StringTokenizer(readstring())
    val list = mutableListOf<Long>()
    while (st!!.hasMoreTokens()) {
        list.add(st!!.nextToken().toLong())
    }
    return list
}

fun h(par: MutableList<Int>, d: MutableList<Int>, i: Int): Int {
    if (i == 1) {
        return -1
    }
    val p = par[i - 2]
    if (d[i - 2] == 0) {
        d[i - 2] = h(par, d, p) + 1
    }
    return d[i - 2]
}

fun main() {
    val v = read_line_of_integers()
    val a = min(v[0], v[1])
    val b = max(v[0], v[1])
    if (a + v[2] <= b) {
        println(2 * (a + v[2]))
    } else {
        println(2 * b + ((v[2] - (b - a)) / 2) * 2)
    }
}

